#!/usr/bin/env bash
# Generated by AREA build.sh. Standalone Bash; no project files are needed at runtime.
set -euo pipefail
PROFILE='ad'

usage() {
  cat <<EOF
Usage: $0 TARGET [--mode all|web-enum] [--ports LIST] [--udp] [--udp-ports 1-100]
          [--scripts] [--web-tools LIST] [--wordlist FILE]
Output: ./AREA_output/<profile>_<timestamp>_<pid>/
Web tools: comma-separated feroxbuster,dirsearch,ffuf (default: feroxbuster,dirsearch)
EOF
}

die() { printf 'AREA: %s\n' "$*" >&2; exit 2; }
find_tool() {
  if command -v "$1" >/dev/null 2>&1; then
    command -v "$1"
  elif [[ -x "$HOME/.local/bin/$1" ]]; then
    printf '%s\n' "$HOME/.local/bin/$1"
  else
    return 1
  fi
}

[[ $# -gt 0 ]] || { usage >&2; exit 2; }
case "$1" in -h|--help) usage; exit 0 ;; esac
TARGET="$1"
shift
[[ "$TARGET" =~ ^[A-Za-z0-9][A-Za-z0-9.:-]*(/[0-9]{1,3})?$ ]] || die 'invalid target'
if [[ "$TARGET" == */* ]]; then
  prefix="${TARGET##*/}"
  if [[ "$TARGET" == *:* ]]; then
    (( 10#$prefix >= 116 && 10#$prefix <= 128 )) || die 'IPv6 CIDR must have at most 4096 addresses'
  else
    (( 10#$prefix >= 20 && 10#$prefix <= 32 )) || die 'IPv4 CIDR must have at most 4096 addresses'
  fi
fi
MODE=all
PORTS=''
UDP=0
UDP_PORTS=20
SCRIPTS=0
WEB_TOOLS='feroxbuster,dirsearch'
WORDLIST=''
while (( $# )); do
  case "$1" in
    --mode) (( $# >= 2 )) || die '--mode needs a value'; MODE="$2"; shift 2 ;;
    --ports) (( $# >= 2 )) || die '--ports needs a value'; PORTS="$2"; shift 2 ;;
    --udp) UDP=1; shift ;;
    --udp-ports) (( $# >= 2 )) || die '--udp-ports needs a value'; UDP_PORTS="$2"; shift 2 ;;
    --scripts) SCRIPTS=1; shift ;;
    --web-tools) (( $# >= 2 )) || die '--web-tools needs a value'; WEB_TOOLS="$2"; shift 2 ;;
    --wordlist) (( $# >= 2 )) || die '--wordlist needs a value'; WORDLIST="$2"; shift 2 ;;
    -h|--help) usage; exit 0 ;;
    *) die "unknown argument: $1" ;;
  esac
done
[[ "$MODE" == all || "$MODE" == web-enum ]] || die 'invalid mode'
[[ "$UDP_PORTS" =~ ^[0-9]+$ ]] && (( 10#$UDP_PORTS >= 1 && 10#$UDP_PORTS <= 100 )) || die 'UDP ports must be 1-100'
if [[ -n "$PORTS" ]]; then
  [[ "$PORTS" =~ ^[0-9]+(-[0-9]+)?(,[0-9]+(-[0-9]+)?)*$ ]] || die 'invalid port list'
  IFS=',' read -r -a port_parts <<< "$PORTS"
  for part in "${port_parts[@]}"; do
    first="${part%%-*}"
    last="${part##*-}"
    (( 10#$first >= 1 && 10#$last <= 65535 && 10#$first <= 10#$last )) || die 'ports must be 1-65535'
  done
fi
IFS=',' read -r -a tools <<< "$WEB_TOOLS"
for tool in "${tools[@]}"; do
  case "$tool" in feroxbuster|dirsearch|ffuf) ;; *) die "unsupported web tool: $tool" ;; esac
done
if [[ " $WEB_TOOLS " == *ffuf* && -z "$WORDLIST" ]]; then
  die 'ffuf requires --wordlist'
fi
[[ -z "$WORDLIST" || -f "$WORDLIST" ]] || die 'wordlist does not exist'
NMAP="$(find_tool nmap)" || die 'nmap is required; run installer-setup.sh first'
RUN_DIR="$(pwd)/AREA_output/${PROFILE}_$(date -u +%Y%m%dT%H%M%SZ)_$$"
mkdir -p "$RUN_DIR/web"
printf 'profile\t%s\ntarget\t%s\nmode\t%s\nstarted_utc\t%s\n' "$PROFILE" "$TARGET" "$MODE" "$(date -u +%FT%TZ)" > "$RUN_DIR/manifest.tsv"
printf 'AREA output: %s\n' "$RUN_DIR"

scan=("$NMAP" -Pn -sT -sV -oX "$RUN_DIR/tcp.xml" -oG "$RUN_DIR/tcp.gnmap")
if [[ -n "$PORTS" ]]; then
  scan+=(-p "$PORTS")
elif [[ "$PROFILE" == ad ]]; then
  scan+=(-p '53,88,135,139,389,445,464,636,3268,3269,3389,5985,5986')
else
  scan+=(--top-ports 1000)
fi
(( SCRIPTS == 0 )) || scan+=(-sC)
scan+=(-- "$TARGET")
"${scan[@]}" > "$RUN_DIR/tcp.log" 2> "$RUN_DIR/tcp.err" || { cat "$RUN_DIR/tcp.err" >&2; exit 1; }

if (( UDP )); then
  udp_scan=("$NMAP" -Pn -sU -sV --top-ports "$UDP_PORTS" -oX "$RUN_DIR/udp.xml" -oG "$RUN_DIR/udp.gnmap")
  (( SCRIPTS == 0 )) || udp_scan+=(-sC)
  udp_scan+=(-- "$TARGET")
  "${udp_scan[@]}" > "$RUN_DIR/udp.log" 2> "$RUN_DIR/udp.err" || printf 'AREA: UDP scan failed; see %s\n' "$RUN_DIR/udp.err" >&2
fi

# Parse Nmap's grepable output for open HTTP TCP services. Keep XML as raw evidence.
awk -F 'Ports: ' '/Ports: / {
  host=$1; sub(/^Host: /, "", host); sub(/ .*/, "", host)
  count=split($2, entries, ", ")
  for (i=1; i<=count; i++) {
    split(entries[i], field, "/")
    port=field[1]; state=field[2]; protocol=field[3]; service=tolower(field[5])
    if (state!="open" || protocol!="tcp") continue
    if (port !~ /^(80|81|443|8000|8008|8080|8081|8443|8888)$/ && service !~ /http/) continue
    scheme=(port==443 || port==8443 || service ~ /https|ssl/) ? "https" : "http"
    address=host; if (address ~ /:/) address="[" address "]"
    print scheme "://" address ":" port
  }
}' "$RUN_DIR/tcp.gnmap" | sort -u > "$RUN_DIR/web_urls.txt"

index=0
while IFS= read -r url; do
  [[ -n "$url" ]] || continue
  index=$((index + 1))
  for tool in "${tools[@]}"; do
    executable="$(find_tool "$tool")" || { printf 'AREA: %s missing; skipped\n' "$tool" >&2; continue; }
    case "$tool" in
      feroxbuster) "$executable" --url "$url" --json --silent --stdout > "$RUN_DIR/web/feroxbuster_${index}.jsonl" 2> "$RUN_DIR/web/feroxbuster_${index}.err" || true ;;
      dirsearch) "$executable" -u "$url" --format json --output "$RUN_DIR/web/dirsearch_${index}.json" > "$RUN_DIR/web/dirsearch_${index}.log" 2> "$RUN_DIR/web/dirsearch_${index}.err" || true ;;
      ffuf) "$executable" -u "${url%/}/FUZZ" -w "$WORDLIST" -of json -o "$RUN_DIR/web/ffuf_${index}.json" > "$RUN_DIR/web/ffuf_${index}.log" 2> "$RUN_DIR/web/ffuf_${index}.err" || true ;;
    esac
  done
done < "$RUN_DIR/web_urls.txt"
printf 'web_targets\t%s\nfinished_utc\t%s\n' "$(wc -l < "$RUN_DIR/web_urls.txt" | tr -d ' ')" "$(date -u +%FT%TZ)" >> "$RUN_DIR/manifest.tsv"
printf 'AREA finished: %s\n' "$RUN_DIR"
